import React, { useState } from 'react';
import "./ReportarModal,css"
const ReportarModal = ({ petName, onClose, onReport }) => {
  const [telefono, setTelefono] = useState('');
  const [dondeLoViste, setDondeLoViste] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onReport({ telefono, dondeLoViste });
    onClose(); // Cerrar el modal
  };

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <h2>Reportar info de {petName}</h2>
        <form onSubmit={handleSubmit}>
          <label>
            TELÉFONO
            <input
              type="text"
              value={telefono}
              onChange={(e) => setTelefono(e.target.value)}
              required
            />
          </label>
          <label>
            ¿DÓNDE LO VISTE?
            <input
              type="text"
              value={dondeLoViste}
              onChange={(e) => setDondeLoViste(e.target.value)}
              required
            />
          </label>
          <button type="submit">Enviar información</button>
          <button type="button" onClick={onClose}>Cancelar</button>
        </form>
      </div>
    </div>
  );
};


export default ReportarModal;
